import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.Ddyno5UB.js";const c=JSON.parse('{"title":"Storage, Filesystems, and LVM","description":"","frontmatter":{},"headers":[],"relativePath":"linux/storage-and-lvm.md","filePath":"linux/storage-and-lvm.md"}'),t={name:"linux/storage-and-lvm.md"};function l(h,s,p,o,d,r){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="storage-filesystems-and-lvm" tabindex="-1">Storage, Filesystems, and LVM <a class="header-anchor" href="#storage-filesystems-and-lvm" aria-label="Permalink to &quot;Storage, Filesystems, and LVM&quot;">​</a></h1><p>Managing physical and logical storage is a foundational skill in Linux administration.</p><h2 id="filesystems" tabindex="-1">Filesystems <a class="header-anchor" href="#filesystems" aria-label="Permalink to &quot;Filesystems&quot;">​</a></h2><p>A filesystem dictates how data is stored and retrieved on a disk.</p><h3 id="common-filesystems" tabindex="-1">Common Filesystems <a class="header-anchor" href="#common-filesystems" aria-label="Permalink to &quot;Common Filesystems&quot;">​</a></h3><ul><li><strong>ext4</strong>: The standard Linux filesystem for many years. Highly stable and well-supported.</li><li><strong>XFS</strong>: A high-performance journaling file system created by Silicon Graphics. Often the default in RHEL/CentOS. It excels at handling large files and parallel I/O.</li><li><strong>Btrfs</strong>: A modern copy-on-write (CoW) filesystem with built-in snapshotting and volume management.</li></ul><h3 id="creating-and-mounting" tabindex="-1">Creating and Mounting <a class="header-anchor" href="#creating-and-mounting" aria-label="Permalink to &quot;Creating and Mounting&quot;">​</a></h3><p>To use a raw disk, you must format it with a filesystem and mount it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Format a partition (/dev/sdb1) with ext4</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkfs.ext4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sdb1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Create a mount point directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/data</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Mount the filesystem</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sdb1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/data</span></span></code></pre></div><h3 id="persistent-mounting-etc-fstab" tabindex="-1">Persistent Mounting (<code>/etc/fstab</code>) <a class="header-anchor" href="#persistent-mounting-etc-fstab" aria-label="Permalink to &quot;Persistent Mounting (\`/etc/fstab\`)&quot;">​</a></h3><p>To ensure a disk is mounted automatically on boot, it must be added to <code>/etc/fstab</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># /etc/fstab example using UUID (recommended over /dev/sdb1)</span></span>
<span class="line"><span>UUID=1234abcd-56ef-78gh-90ij-klmnopqrstuv  /mnt/data  ext4  defaults  0  2</span></span></code></pre></div><h2 id="lvm-logical-volume-management" tabindex="-1">LVM (Logical Volume Management) <a class="header-anchor" href="#lvm-logical-volume-management" aria-label="Permalink to &quot;LVM (Logical Volume Management)&quot;">​</a></h2><p>LVM adds a layer of abstraction between the physical disks and the filesystem. Instead of mounting a physical partition directly, you mount a &quot;Logical Volume&quot;.</p><p>This allows you to dynamically resize filesystems or stripe them across multiple physical disks without downtime.</p><h3 id="the-lvm-hierarchy" tabindex="-1">The LVM Hierarchy <a class="header-anchor" href="#the-lvm-hierarchy" aria-label="Permalink to &quot;The LVM Hierarchy&quot;">​</a></h3><ol><li><strong>Physical Volumes (PV)</strong>: The actual raw disks or partitions (e.g., <code>/dev/sdb</code>).</li><li><strong>Volume Groups (VG)</strong>: A pool of storage created by combining one or more Physical Volumes.</li><li><strong>Logical Volumes (LV)</strong>: Slices of the Volume Group that act like regular partitions, which you then format and mount.</li></ol><h3 id="example-creating-an-lvm-stack" tabindex="-1">Example: Creating an LVM Stack <a class="header-anchor" href="#example-creating-an-lvm-stack" aria-label="Permalink to &quot;Example: Creating an LVM Stack&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Initialize the disk as a Physical Volume</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pvcreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sdb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Create a Volume Group named &#39;data_vg&#39; using the PV</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vgcreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data_vg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sdb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Create a 50GB Logical Volume named &#39;app_lv&#39; from the VG</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lvcreate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 50G</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app_lv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data_vg</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Format the new LV with XFS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkfs.xfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/data_vg/app_lv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. Mount it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/data_vg/app_lv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/app</span></span></code></pre></div><h3 id="extending-an-lvm-volume-dynamically" tabindex="-1">Extending an LVM Volume dynamically <a class="header-anchor" href="#extending-an-lvm-volume-dynamically" aria-label="Permalink to &quot;Extending an LVM Volume dynamically&quot;">​</a></h3><p>The true power of LVM is resizing on the fly. If you run out of space, you can add another disk to the VG, extend the LV, and grow the filesystem without unmounting!</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add 10GB to the Logical Volume</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lvextend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +10G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/data_vg/app_lv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Grow the XFS filesystem to use the new space</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xfs_growfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/app</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># (If using ext4, you would use: sudo resize2fs /dev/data_vg/app_lv)</span></span></code></pre></div>`,22)])])}const g=a(t,[["render",l]]);export{c as __pageData,g as default};
